// It reads to END OF INPUT even after it has collected `limit` of them, and that is deliberate twice
// over. The caller reads this same stream through an io.TeeReader that echoes it, so stopping the
// scan early would stop the ECHO early and the agent would lose the tail of its own test output.
// And the count it returns is what makes truncation visible: the collector used to return the moment
// it hit the limit, so `Scanned` was a restatement of the limit and `Omitted` was never set at all —
// a machine consumer could not tell exactly eight names from eight out of ninety.
//
// Nothing is retained beyond one line and a bounded name set, so the memory cost does not depend on
// how much the build printed.
func explainCandidates(input io.Reader, limit int) ([]explainCandidate, int, error) {
	if limit <= 0 {
		limit = explainMaxSymbols
	}
	// The name budget bounds what an UNTRUSTED build can make this process remember; it is not a
	// second opinion on what the CALLER may ask for. Those are different questions and only one of
	// them has an attacker on the other end. Collection stops when the set stops growing, so a
	// budget below `limit` silently answered a smaller question than the one asked: --max-symbols
	// 1500 resolved 1024 and reported nothing. Raising the budget to meet the limit costs nothing
	// that was not already spent — `candidates` is sized by `limit` regardless, and each entry
	// there is strictly heavier than a set key — while the build still cannot push either past a
	// bound the caller chose.
	budget := explainMaxScannedNames
	if limit > budget {
		budget = limit
	}
	seen := map[string]bool{}
	var candidates []explainCandidate
	scanned := 0
	reader := bufio.NewReaderSize(input, explainReadBufferBytes)
	buffer := make([]byte, 0, explainReadBufferBytes)
	for {
		var readErr error
		buffer, readErr = explainReadLine(buffer[:0], reader, explainMaxLineBytes)
		line := string(buffer)
		var file, owner string
		context := false
		for _, pattern := range explainErrorPatterns {
			for _, match := range pattern.FindAllStringSubmatch(line, -1) {
				if len(match) < 2 {
					continue
				}
				name := match[1]
				// A qualified name resolves on its last segment: `pkg.Foo` is indexed as `Foo`.
				if cut := strings.LastIndex(name, "."); cut >= 0 && cut+1 < len(name) {
					name = name[cut+1:]
				}
				if name == "" || seen[name] {
					continue
				}
				if len(seen) >= budget {
					// The set is what dedupes, so once it stops growing, collecting stops with it —
					// otherwise a name already reported could be reported a second time. Scanned
					// saturates here rather than lying about a build this broken.
					continue
				}
				seen[name] = true
				scanned++
				if len(candidates) >= limit {
					continue
				}
				if !context {
					// Read once per line, not once per match: every name on one error line shares
					// that line's file and type context.
					file, owner, context = explainFirstMatch(explainLocationPatterns, line), explainFirstMatch(explainOwnerPatterns, line), true
				}
				candidates = append(candidates, explainCandidate{Name: name, File: file, Owner: owner})
			}
		}
		if readErr != nil {
			if errors.Is(readErr, io.EOF) {
				return candidates, scanned, nil
			}
			return candidates, scanned, readErr
		}
	}
}

// explainReadLine appends the next line, without its terminator, to dst — reading at most limit
// bytes of it and DISCARDING the rest of an over-long one so the read continues on the line after.
//
// bufio.Scanner cannot do that. It returns ErrTooLong on a token past its buffer and then refuses to
// scan again, permanently, so ONE oversized line silently threw away every diagnostic that came
// after it: a linker dump, a bundled source map quoted inside a TypeScript error, a test printing a
// large diff on one line. The names in the errors that followed were never looked at. Tolerating
// ErrTooLong at the call site kept the command from failing, but the scan was already over.
//
// Memory stays bounded the same way it did: ReadSlice never allocates past the reader's own buffer,
// and this keeps at most `limit` bytes of any single line — the ceiling bufio.Scanner was configured
// with — regardless of how long the line actually is.
func explainReadLine(dst []byte, reader *bufio.Reader, limit int) ([]byte, error) {
	for {
		chunk, err := reader.ReadSlice('\n')
		// ReadSlice's chunk is only valid until the next read, so copy before looping.
		if room := limit - len(dst); room > 0 {
			if len(chunk) > room {
				chunk = chunk[:room]
			}
			dst = append(dst, chunk...)
		}
		if errors.Is(err, bufio.ErrBufferFull) {
			// Still inside the SAME line. Keep going so the next call starts on the next one.
			continue
		}
		return bytes.TrimRight(dst, "\r\n"), err
	}
}

	}
}

// Truncation has to be VISIBLE. The collector used to stop the moment it had the limit, so Scanned
// was a restatement of the limit and Omitted was never set: a consumer could not tell a build that
// named exactly two symbols from one that named ten.
func TestExplainReportsHowManyNamesTheBuildOmitted(t *testing.T) {
	t.Parallel()
	build := strings.Join([]string{
		"./a.go:1:1: undefined: alpha",
		"./b.go:2:1: undefined: beta",
		"./c.go:3:1: undefined: gamma",
		"./d.go:4:1: undefined: delta",
		"./e.go:5:1: undefined: epsilon",
	}, "\n")
	candidates, scanned, err := explainCandidates(strings.NewReader(build), 2)
	if err != nil {
		t.Fatal(err)
	}
	if len(candidates) != 2 {
		t.Fatalf("collected %d candidates, want 2", len(candidates))
	}
	if scanned != 5 {
		t.Fatalf("scanned = %d, want 5: the scan has to keep counting past the limit", scanned)
	}
